local KeyMaker = {}
local PRODUCTS = {
    iron_key = { name = "Železen ključ", ironCost = 1, time = 1, cost = 5, security = 5, description = "Preprost železen ključ." },
    steel_key = { name = "Jeklen ključ", steelCost = 1, time = 2, cost = 16, security = 8, prestige = 1, description = "Jeklen ključ z natančnim zobovjem." },
    brass_key = { name = "Medeninast ključ", brassCost = 2, time = 3, cost = 36, security = 12, prestige = 2, description = "Medeninast ključ za okrasna ključavnice." },
    silver_key = { name = "Srebrn ključ", silverCost = 2, time = 4, cost = 75, security = 16, prestige = 5, description = "Srebrn ključ za zakladne sobe." },
    gold_key = { name = "Zlat ključ", goldCost = 1, silverCost = 1, time = 5, cost = 160, security = 22, prestige = 9, happiness = 1, description = "Zlat ključ za kraljevske sobe." },
    royal_skeleton_key = { name = "Kraljevski glavni ključ", goldCost = 2, silverCost = 2, steelCost = 1, jewelCost = 1, time = 8, cost = 450, security = 35, prestige = 25, happiness = 4, description = "Glavni ključ z draguljnim grbom za kraljevski zaklad." },
}
local BUILDINGS = {
    workshop = { name = "Ključarska delavnica", cost = { gold = 200, wood = 100 }, upkeep = 5, qualityBonus = 5 },
    forge = { name = "Kovačija ključev", cost = { gold = 650, wood = 200, stone = 150 }, upkeep = 16, qualityBonus = 15 },
    filing_room = { name = "Brusilnica", cost = { gold = 1100, wood = 250, stone = 250, silver = 20 }, upkeep = 26, qualityBonus = 22 },
    royal_key_atelier = { name = "Kraljevski atelje ključev", cost = { gold = 3200, wood = 400, stone = 500, gold = 30 }, upkeep = 62, qualityBonus = 36, prestigeBonus = 18 },
}
KeyMaker.ironStock = 14; KeyMaker.steelStock = 10; KeyMaker.brassStock = 6; KeyMaker.silverStock = 4; KeyMaker.goldStock = 3; KeyMaker.jewelStock = 3
KeyMaker.productStock = {}; KeyMaker.buildings = {}; KeyMaker.maker = nil; KeyMaker.activeMaking = {}; KeyMaker.totalProducts = 0; KeyMaker.dayTimer = 0
function KeyMaker.init() KeyMaker.ironStock=14; KeyMaker.steelStock=10; KeyMaker.brassStock=6; KeyMaker.silverStock=4; KeyMaker.goldStock=3; KeyMaker.jewelStock=3; KeyMaker.productStock={}; KeyMaker.buildings={}; KeyMaker.maker=nil; KeyMaker.activeMaking={}; KeyMaker.totalProducts=0; KeyMaker.dayTimer=0; print("[KeyMaker] Royal Key Maker System initialized (6 products, 4 buildings)") end
function KeyMaker.hireMaker(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; KeyMaker.maker={name=n or ("Ključar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ključar najet: %s (spretnost: %d)",KeyMaker.maker.name,s),"success") end; return true end
function KeyMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function KeyMaker.build(id) local ok,e=KeyMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(KeyMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function KeyMaker.getQualityBonus() local b=0; for _,bd in ipairs(KeyMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function KeyMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and KeyMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and KeyMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.brassCost and KeyMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and KeyMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and KeyMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and KeyMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #KeyMaker.buildings==0 then return false,"Potrebna delavnica" end; if not KeyMaker.maker then return false,"Potreben ključar" end; return true end
function KeyMaker.make(pt,qty) qty=qty or 5; local ok,e=KeyMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then KeyMaker.ironStock=KeyMaker.ironStock-d.ironCost*qty end; if d.steelCost then KeyMaker.steelStock=KeyMaker.steelStock-d.steelCost*qty end; if d.brassCost then KeyMaker.brassStock=KeyMaker.brassStock-d.brassCost*qty end; if d.silverCost then KeyMaker.silverStock=KeyMaker.silverStock-d.silverCost*qty end; if d.goldCost then KeyMaker.goldStock=KeyMaker.goldStock-d.goldCost*qty end; if d.jewelCost then KeyMaker.jewelStock=KeyMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if KeyMaker.maker then t=math.max(1,t-math.floor(KeyMaker.maker.skill/15)) end; table.insert(KeyMaker.activeMaking,{id="key_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,security=d.security or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function KeyMaker.completeMaking(m) local q=1.0+(KeyMaker.getQualityBonus()/100); if KeyMaker.maker then q=q+(KeyMaker.maker.skill/200) end; q=math.min(2.0,q); KeyMaker.productStock[m.productType]=(KeyMaker.productStock[m.productType] or 0)+m.quantity; KeyMaker.totalProducts=KeyMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if KeyMaker.maker then KeyMaker.maker.itemsMade=KeyMaker.maker.itemsMade+m.quantity; if math.random()<0.15 then KeyMaker.maker.skill=math.min(100,KeyMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ključi izdelani: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end end
function KeyMaker.update(dt) if not _G.state then return end; KeyMaker.dayTimer=KeyMaker.dayTimer+dt; if KeyMaker.dayTimer>=30 then KeyMaker.dayTimer=0; for i=#KeyMaker.activeMaking,1,-1 do local m=KeyMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then KeyMaker.completeMaking(m); table.remove(KeyMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(KeyMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if KeyMaker.maker then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function KeyMaker.getStats() return {ironStock=KeyMaker.ironStock,steelStock=KeyMaker.steelStock,brassStock=KeyMaker.brassStock,silverStock=KeyMaker.silverStock,goldStock=KeyMaker.goldStock,jewelStock=KeyMaker.jewelStock,productStock=KeyMaker.productStock,numBuildings=#KeyMaker.buildings,hasMaker=KeyMaker.maker~=nil,makerName=KeyMaker.maker and KeyMaker.maker.name or "—",makerSkill=KeyMaker.maker and KeyMaker.maker.skill or 0,activeMaking=#KeyMaker.activeMaking,totalProducts=KeyMaker.totalProducts} end
return KeyMaker
